import{_ as i,c as a,a2 as e,o as t}from"./chunks/framework.DMeDE4-B.js";const m=JSON.parse('{"title":"2025.1.0","description":"","frontmatter":{"title":"2025.1.0"},"headers":[],"relativePath":"changelog/2025.1.0.md","filePath":"changelog/2025.1.0.md","lastUpdated":1736918785000}'),r={name:"changelog/2025.1.0.md"};function h(o,l,u,n,d,s){return t(),a("div",null,l[0]||(l[0]=[e('<h1 id="🎉-view-shadcn-ui-2025-1-0-发布-新年新气象-多个重磅组件来袭" tabindex="-1">🎉 View Shadcn UI 2025.1.0 发布：新年新气象，多个重磅组件来袭！ <a class="header-anchor" href="#🎉-view-shadcn-ui-2025-1-0-发布-新年新气象-多个重磅组件来袭" aria-label="Permalink to &quot;🎉 View Shadcn UI 2025.1.0 发布：新年新气象，多个重磅组件来袭！&quot;">​</a></h1><br><p>亲爱的开发者们：</p><p>我们很高兴地宣布 View Shadcn UI <code>2025.1.0</code> 版本正式发布！本次更新带来了图片查看器、提及(@)组件等重磅新功能，同时对多个现有组件进行了全面优化和改进。</p><h2 id="🚀-重要链接" tabindex="-1">🚀 重要链接 <a class="header-anchor" href="#🚀-重要链接" aria-label="Permalink to &quot;🚀 重要链接&quot;">​</a></h2><ul><li>GitHub 仓库：<a href="https://github.com/devlive-community/view-shadcn-ui" target="_blank" rel="noreferrer">https://github.com/devlive-community/view-shadcn-ui</a></li><li>官方文档：<a href="https://view-shadcn-ui.devlive.org/" target="_blank" rel="noreferrer">https://view-shadcn-ui.devlive.org/</a></li><li>在线演练场：<a href="https://playground.view-shadcn-ui.devlive.org/" target="_blank" rel="noreferrer">https://playground.view-shadcn-ui.devlive.org/</a></li></ul><h2 id="📦-新版本亮点" tabindex="-1">📦 新版本亮点 <a class="header-anchor" href="#📦-新版本亮点" aria-label="Permalink to &quot;📦 新版本亮点&quot;">​</a></h2><h3 id="🖼️-全新图片组件" tabindex="-1">🖼️ 全新图片组件 <a class="header-anchor" href="#🖼️-全新图片组件" aria-label="Permalink to &quot;🖼️ 全新图片组件&quot;">​</a></h3><ul><li>支持图片预览和图片组</li><li>强大的预览功能： <ul><li>支持键盘快捷键操作</li><li>图片缩放、旋转和还原</li><li>流畅的切换动画效果</li></ul></li><li>支持自定义加载方式和失败处理</li><li>支持图片组 hover 动态效果</li><li>灵活的边框配置选项</li></ul><h3 id="📝-提及-组件" tabindex="-1">📝 提及(@)组件 <a class="header-anchor" href="#📝-提及-组件" aria-label="Permalink to &quot;📝 提及(@)组件&quot;">​</a></h3><ul><li>完整的提及功能实现： <ul><li>支持自定义提及符号</li><li>键盘快捷键操作</li><li>展开/关闭动画效果</li></ul></li><li>丰富的配置选项： <ul><li>支持异步数据加载</li><li>最大提及数量限制</li><li>多种尺寸选择</li><li>禁用特定提及项</li></ul></li><li>表单集成支持</li><li>自定义插槽支持</li><li>横向滚动效果优化</li></ul><h3 id="🎠-轮播组件增强" tabindex="-1">🎠 轮播组件增强 <a class="header-anchor" href="#🎠-轮播组件增强" aria-label="Permalink to &quot;🎠 轮播组件增强&quot;">​</a></h3><ul><li>支持自动播放配置</li><li>可自定义轮播方向</li><li>灵活的高度设置</li><li>支持上下插槽</li><li>可配置指示器</li></ul><h3 id="💅-现有组件优化" tabindex="-1">💅 现有组件优化 <a class="header-anchor" href="#💅-现有组件优化" aria-label="Permalink to &quot;💅 现有组件优化&quot;">​</a></h3><ul><li>选项卡组件： <ul><li>新增线型样式</li><li>支持内容过多时滑动</li><li>优化关闭按钮样式</li></ul></li><li>骨架屏：支持自定义尺寸</li><li>选择器：新增加载状态配置</li><li>树组件： <ul><li>支持节点选中状态</li><li>修复 v-model 数据渲染问题</li></ul></li><li>代码编辑器： <ul><li>优化搜索面板位置</li><li>支持焦点事件处理</li><li>修复多编辑器共存问题</li></ul></li></ul><h3 id="🐛-问题修复" tabindex="-1">🐛 问题修复 <a class="header-anchor" href="#🐛-问题修复" aria-label="Permalink to &quot;🐛 问题修复&quot;">​</a></h3><ul><li>修复多个组件在 flex 布局下的显示异常</li><li>修复头像和按钮组件的变形问题</li><li>修复输入框前缀/后缀影响占位符位置的问题</li><li>修复切换组件返回值类型问题</li><li>优化代码编辑器清理机制</li></ul><h3 id="📚-文档升级" tabindex="-1">📚 文档升级 <a class="header-anchor" href="#📚-文档升级" aria-label="Permalink to &quot;📚 文档升级&quot;">​</a></h3><ul><li>全面重构文档结构</li><li>优化使用指南</li><li>改进组件示例</li><li>更新工具函数文档</li></ul><h2 id="🔜-后续规划" tabindex="-1">🔜 后续规划 <a class="header-anchor" href="#🔜-后续规划" aria-label="Permalink to &quot;🔜 后续规划&quot;">​</a></h2><p>我们将继续完善组件库功能，提升开发体验，欢迎社区参与贡献和提供反馈。</p><h2 id="🤝-参与贡献" tabindex="-1">🤝 参与贡献 <a class="header-anchor" href="#🤝-参与贡献" aria-label="Permalink to &quot;🤝 参与贡献&quot;">​</a></h2><p>如果您在使用过程中遇到问题或有新的想法，欢迎：</p><ul><li>提交 Issue：<a href="https://github.com/devlive-community/view-shadcn-ui/issues" target="_blank" rel="noreferrer">https://github.com/devlive-community/view-shadcn-ui/issues</a></li><li>贡献代码：<a href="https://github.com/devlive-community/view-shadcn-ui/pulls" target="_blank" rel="noreferrer">https://github.com/devlive-community/view-shadcn-ui/pulls</a></li></ul><p>特别感谢所有为这个版本贡献代码和反馈的开发者们！</p>',25)]))}const p=i(r,[["render",h]]);export{m as __pageData,p as default};
